"""Independent reference implementation of the Batch Rename Studio plan contract.

Written by the lead from the specification text alone, deliberately NOT by
reading the C# implementation. Used as an oracle: the exe's plan.json must agree
with this one on every fixture case.

Known intentional divergences from .NET that fixtures must avoid:
  - str.upper()/lower() differs from ToUpperInvariant for 'sz'-ligature, dotted-I,
    and ligature codepoints  -> fixtures use only ASCII/accented-Latin/CJK.
  - Python sorts by codepoint, .NET CompareOrdinal by UTF-16 code unit
    -> fixtures contain no astral-plane (non-BMP) characters.
"""

import json
import os
import re
import sys

RESERVED = {"CON", "PRN", "AUX", "NUL"} | {f"COM{i}" for i in range(1, 10)} | {
    f"LPT{i}" for i in range(1, 10)
}
ILLEGAL = set('<>:"/\\|?*')


def split_name(name):
    dot = name.rfind(".")
    if dot > 0:
        return name[:dot], name[dot + 1:]
    return name, ""


def join_name(base, ext):
    return base + "." + ext if ext else base


def title_case(s):
    out = []
    in_run = False
    for ch in s:
        if ch.isalpha():
            out.append(ch.lower() if in_run else ch.upper())
            in_run = True
        else:
            out.append(ch)
            in_run = False
    return "".join(out)


def render_sequence(pattern, value):
    m = re.search(r"\{n:(0+)\}", pattern)
    if not m:
        return pattern
    width = len(m.group(1))
    if value < 0:
        text = "-" + str(-value).rjust(width, "0")
    else:
        text = str(value).rjust(width, "0")
    return pattern[:m.start()] + text + pattern[m.end():]


def dotnet_replacement_to_python(rw):
    # $1 -> \1 ; $$ -> $ ; leave everything else literal
    out = []
    i = 0
    while i < len(rw):
        c = rw[i]
        if c == "$" and i + 1 < len(rw):
            nxt = rw[i + 1]
            if nxt == "$":
                out.append("$")
                i += 2
                continue
            if nxt.isdigit():
                out.append("\\" + nxt)
                i += 2
                continue
        if c == "\\":
            out.append("\\\\")
            i += 1
            continue
        out.append(c)
        i += 1
    return "".join(out)


def apply_extension(ext, step):
    mode = step["mode"]
    if mode == "lower":
        return ext.lower()
    if mode == "upper":
        return ext.upper()
    if mode == "set":
        return step.get("value", "")
    raise ValueError("extension.mode " + mode)


