        if step.get("regex", False):
            return re.sub(find, dotnet_replacement_to_python(rw), s, flags=flags)
        return re.sub(re.escape(find), lambda _m: rw, s, flags=flags)
    if op == "insert":
        text = step.get("text", "")
        pos = step.get("position", "prefix")
        if pos == "prefix":
            return text + s
        if pos == "suffix":
            return s + text
        idx = max(0, min(int(step.get("index", 0)), len(s)))
        return s[:idx] + text + s[idx:]
