                reason = ""
            else:
                status = "ok"
                reason = ""
        counts[status] += 1
        items.append({"original": name, "proposed": p, "status": status, "reason": reason})

    return {
        "schemaVersion": 1,
        "items": items,
        "summary": {
            "total": len(items),
            "ok": counts["ok"],
            "collision": counts["collision"],
            "unchanged": counts["unchanged"],
            "invalid": counts["invalid"],
        },
    }


if __name__ == "__main__":
    directory, rules_path, out_path = sys.argv[1], sys.argv[2], sys.argv[3]
    with open(rules_path, "r", encoding="utf-8") as fh:
        rules = json.load(fh)
