    with open(out_path, "w", encoding="utf-8", newline="\n") as fh:
        json.dump(plan, fh, ensure_ascii=False, indent=2)
        fh.write("\n")
    s = plan["summary"]
    print("oracle: total={total} ok={ok} collision={collision} unchanged={unchanged} "
          "invalid={invalid}".format(**s))

