using System.Text.RegularExpressions;
using BatchRenameStudio.Core.Rules;

namespace BatchRenameStudio.Core.Engine;

public static class NameEngine
{
    /// <summary>Rule 2 split. Returned Ext never contains the dot.</summary>
    public static (string Base, string Ext) Split(string fileName)
    {
        int dot = fileName.LastIndexOf('.');
        if (dot > 0)
        {
            return (fileName.Substring(0, dot), fileName.Substring(dot + 1));
        }

        return (fileName, "");
    }

    /// <summary>Rule 12 reassembly: b + "." + ext when ext is non-empty, else b.</summary>
    public static string Join(string baseName, string ext)
    {
        return ext.Length == 0 ? baseName : baseName + "." + ext;
    }

    /// <summary>Rule 10 title casing.</summary>
    public static string ToTitleCase(string value)
    {
        var sb = new System.Text.StringBuilder(value.Length);
        bool inRun = false;
        foreach (char c in value)
        {
            if (char.IsLetter(c))
            {
                sb.Append(inRun ? char.ToLowerInvariant(c) : char.ToUpperInvariant(c));
                inRun = true;
            }
            else
            {
                sb.Append(c);
                inRun = false;
            }
        }

        return sb.ToString();
    }

    /// <summary>Full pipeline for one file. sequenceIndex is 0-based position in processing order.</summary>
    public static string ComputeProposedName(string originalName, RuleSet rules, int sequenceIndex)
    {
        (string b, string e) = Split(originalName);
        string target = rules.ApplyTo == ApplyTo.Name ? b : originalName;

        foreach (RuleStep step in rules.Steps)
        {
            if (step is ExtensionStep extStep)
            {
                if (rules.ApplyTo == ApplyTo.Name)
                {
                    e = ApplyExtension(e, extStep);
                }
                else
                {
                    (string tb, string te) = Split(target);
                    target = Join(tb, ApplyExtension(te, extStep));
                }
            }
            else
            {
                target = ApplyTextStep(target, step, sequenceIndex);
            }
        }

        return rules.ApplyTo == ApplyTo.Name ? Join(target, e) : target;
    }

    private static string ApplyTextStep(string s, RuleStep step, int sequenceIndex)
    {
        switch (step)
        {
            case ReplaceStep replace:
                if (replace.Find.Length == 0)
                {
                    return s;
                }

                if (replace.Regex)
                {
                    return Regex.Replace(
                        s,
                        replace.Find,
                        replace.ReplaceWith,
                        replace.IgnoreCase ? RegexOptions.IgnoreCase : RegexOptions.None);
                }

                return s.Replace(
                    replace.Find,
                    replace.ReplaceWith,
                    replace.IgnoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal);

            case InsertStep insert:
                return insert.Position switch
                {
                    InsertPosition.Prefix => insert.Text + s,
                    InsertPosition.Suffix => s + insert.Text,
                    InsertPosition.Index => s.Insert(Math.Clamp(insert.Index, 0, s.Length), insert.Text),
                    _ => s,
                };

            case RemoveStep remove:
                {
                    int from = Math.Clamp(remove.From, 0, s.Length);
                    int count = Math.Clamp(remove.Count, 0, s.Length - from);
                    return s.Remove(from, count);
                }

            case SequenceStep sequence:
                {
                    int value = sequence.Start + sequence.Step * sequenceIndex;
                    string rendered = SequencePattern.Render(sequence.Pattern, value);
                    return sequence.Position switch
                    {
                        AffixPosition.Prefix => rendered + s,
                        AffixPosition.Suffix => s + rendered,
                        _ => s,
                    };
                }

            case CaseStep caseStep:
                return caseStep.Mode switch
                {
                    CaseMode.Upper => s.ToUpperInvariant(),
                    CaseMode.Lower => s.ToLowerInvariant(),
                    CaseMode.Title => ToTitleCase(s),
                    _ => s,
                };

            default:
                return s;
        }
    }

    private static string ApplyExtension(string ext, ExtensionStep step)
    {
        return step.Mode switch
        {
            ExtensionMode.Lower => ext.ToLowerInvariant(),
            ExtensionMode.Upper => ext.ToUpperInvariant(),
            ExtensionMode.Set => step.Value,
            _ => ext,
        };
    }
}

