using BatchRenameStudio.Core.Engine;
using BatchRenameStudio.Core.Rules;

namespace BatchRenameStudio.Core.Planning;

public static class RenamePlanner
{
    /// <summary>Enumerates the directory (rule 1) and builds the plan.</summary>
    public static RenamePlan Create(string directory, RuleSet rules)
    {
        var entries = new List<FileEntry>();
        foreach (string path in Directory.EnumerateFiles(directory))
