namespace BatchRenameStudio.Core.Engine;

public static class SequencePattern
{
    private static readonly Regex TokenRegex = new(@"\{n:(0+)\}", RegexOptions.Compiled);

    /// <summary>
    /// Finds the FIRST match of {n:(0+)} in the pattern and replaces it with
    /// value formatted to the captured zero-run width. If no match, returns the
    /// pattern verbatim.
