using System.Globalization;
using System.Text;
using System.Text.Json;
using BatchRenameStudio.Core.Planning;

namespace BatchRenameStudio.Core.Execution;

public static class RenameExecutor
{
    private const string TempPrefix = "__brs_";

    /// <summary>Default history location: %LOCALAPPDATA%\BatchRenameStudio\history</summary>
    public static string DefaultHistoryDirectory { get; } = Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        "BatchRenameStudio",
        "history");

    /// <summary>Renames only the plan items whose status is Ok.</summary>
    public static RenameOutcome Apply(string directory, RenamePlan plan, string historyDirectory)
    {
        var operations = new List<RenameOperation>();
        foreach (PlanItem item in plan.Items)
        {
            if (item.Status == ItemStatus.Ok)
            {
                operations.Add(new RenameOperation(item.Original, item.Proposed));
            }
        }

        (int renamed, int failed, List<string> errors, List<RenameOperation> succeeded) =
            ExecuteTwoPhase(directory, operations);

        string? historyPath = null;
        if (succeeded.Count > 0)
        {
            try
            {
                historyPath = WriteHistory(historyDirectory, directory, succeeded);
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
            {
                errors.Add($"history: unable to write history file: {ex.Message}");
            }
        }

        return new RenameOutcome
        {
            Renamed = renamed,
            Failed = failed,
            Errors = errors,
            HistoryPath = historyPath,
        };
    }

    /// <summary>Newest first. Files already undone are excluded.</summary>
    public static IReadOnlyList<HistoryEntry> ListHistory(string historyDirectory)
    {
        var result = new List<HistoryEntry>();
        if (!Directory.Exists(historyDirectory))
        {
            return result;
        }

        foreach (string path in Directory.EnumerateFiles(historyDirectory, "*.json"))
        {
            if (path.EndsWith(".undone.json", StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            try
            {
                (string dir, DateTime ts, int count) = ReadHistoryHeader(path);
                result.Add(new HistoryEntry(path, ts, dir, count));
            }
            catch
            {
                // Skip an unreadable/corrupt history file rather than crash the picker.
            }
        }

        result.Sort((a, b) => b.TimestampUtc.CompareTo(a.TimestampUtc));
        return result;
    }

    public static RenameOutcome Undo(string historyFilePath)
    {
        (string dir, DateTime _, List<RenameOperation> operations) = ReadHistory(historyFilePath);

        var reversed = new List<RenameOperation>(operations.Count);
        foreach (RenameOperation op in operations)
        {
            reversed.Add(new RenameOperation(op.To, op.From));
        }

        (int renamed, int failed, List<string> errors, List<RenameOperation> _) =
            ExecuteTwoPhase(dir, reversed);

        // Only retire the history file once undo actually made progress (or there was
        // nothing to undo in the first place) — a fully-failed attempt should stay
        // offered so the user can retry.
        if (renamed > 0 || operations.Count == 0)
        {
            try
            {
                string undonePath = historyFilePath.EndsWith(".json", StringComparison.OrdinalIgnoreCase)
                    ? historyFilePath[..^".json".Length] + ".undone.json"
                    : historyFilePath + ".undone.json";
                File.Move(historyFilePath, undonePath, overwrite: true);
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
            {
                errors.Add($"history: unable to mark '{historyFilePath}' as undone: {ex.Message}");
            }
        }

        return new RenameOutcome
        {
            Renamed = renamed,
            Failed = failed,
            Errors = errors,
            HistoryPath = null,
        };
    }

    /// <summary>
    /// Two-phase rename shared by Apply and Undo: every source is first moved to a
    /// unique temp name in the same folder, then every temp is moved to its target.
    /// A phase-1 failure rolls everything already staged back to its original name
    /// and reports the whole batch as failed — nothing is left half-applied. A
    /// phase-2 failure is isolated to that one entry.
    /// </summary>
    private static (int Renamed, int Failed, List<string> Errors, List<RenameOperation> Succeeded) ExecuteTwoPhase(
        string directory, List<RenameOperation> operations)
    {
        var errors = new List<string>();
        if (operations.Count == 0)
        {
            return (0, 0, errors, new List<RenameOperation>());
        }

        var staged = new List<(string Temp, string Target, string Original)>();

        foreach (RenameOperation op in operations)
        {
            string sourcePath = Path.Combine(directory, op.From);
            string tempPath = UniqueTempPath(directory);
            try
            {
                File.Move(sourcePath, tempPath);
            }
            catch (Exception ex)
            {
                foreach ((string temp, string _, string original) in staged)
                {
                    try
                    {
                        File.Move(temp, Path.Combine(directory, original));
                    }
                    catch
                    {
                        // Best effort restore; nothing more we can do here.
                    }
                }

                errors.Add($"rename failed for '{op.From}' -> '{op.To}': {ex.Message}");
                return (0, operations.Count, errors, new List<RenameOperation>());
            }

            staged.Add((tempPath, op.To, op.From));
        }

        int renamed = 0;
        int failed = 0;
        var succeeded = new List<RenameOperation>();
        foreach ((string temp, string target, string original) in staged)
        {
            string targetPath = Path.Combine(directory, target);
            try
            {
                File.Move(temp, targetPath);
                renamed++;
                succeeded.Add(new RenameOperation(original, target));
            }
            catch (Exception ex)
            {
                failed++;
                errors.Add($"rename failed for '{original}' -> '{target}': {ex.Message}");
                try
                {
                    File.Move(temp, Path.Combine(directory, original));
                }
                catch (Exception restoreEx)
                {
                    errors.Add($"restore failed for '{original}': {restoreEx.Message}");
                }
            }
        }

        return (renamed, failed, errors, succeeded);
    }

    private static string UniqueTempPath(string directory)
    {
        string path;
        do
        {
            path = Path.Combine(directory, TempPrefix + Guid.NewGuid().ToString("N") + ".tmp");
        }
        while (File.Exists(path));

        return path;
    }

    private static string WriteHistory(string historyDirectory, string directory, List<RenameOperation> operations)
    {
        Directory.CreateDirectory(historyDirectory);

        DateTime now = DateTime.UtcNow;
        string fileName = now.ToString("yyyyMMdd-HHmmss-fff", CultureInfo.InvariantCulture) + ".json";
        string path = Path.Combine(historyDirectory, fileName);

        var options = new JsonWriterOptions { Indented = true };
        using var stream = new MemoryStream();
        using (var writer = new Utf8JsonWriter(stream, options))
        {
            writer.WriteStartObject();
            writer.WriteNumber("schemaVersion", 1);
            writer.WriteString("directory", directory);
            writer.WriteString("timestampUtc", now.ToString("O", CultureInfo.InvariantCulture));

            writer.WriteStartArray("operations");
            foreach (RenameOperation op in operations)
            {
                writer.WriteStartObject();
                writer.WriteString("from", op.From);
                writer.WriteString("to", op.To);
                writer.WriteEndObject();
            }

            writer.WriteEndArray();
            writer.WriteEndObject();
        }

        var encoding = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false);
        File.WriteAllText(path, Encoding.UTF8.GetString(stream.ToArray()), encoding);
        return path;
    }

    private static (string Directory, DateTime TimestampUtc, int OperationCount) ReadHistoryHeader(string path)
    {
        string json = File.ReadAllText(path);
        using JsonDocument doc = JsonDocument.Parse(json);
        JsonElement root = doc.RootElement;
        string directory = root.GetProperty("directory").GetString() ?? "";
        DateTime ts = DateTime.Parse(
            root.GetProperty("timestampUtc").GetString() ?? "",
            CultureInfo.InvariantCulture,
            DateTimeStyles.RoundtripKind);
        int count = root.GetProperty("operations").GetArrayLength();
        return (directory, ts, count);
    }

    private static (string Directory, DateTime TimestampUtc, List<RenameOperation> Operations) ReadHistory(string path)
    {
        string json = File.ReadAllText(path);
        using JsonDocument doc = JsonDocument.Parse(json);
        JsonElement root = doc.RootElement;
        string directory = root.GetProperty("directory").GetString() ?? "";
        DateTime ts = DateTime.Parse(
            root.GetProperty("timestampUtc").GetString() ?? "",
            CultureInfo.InvariantCulture,
            DateTimeStyles.RoundtripKind);

        var operations = new List<RenameOperation>();
        foreach (JsonElement el in root.GetProperty("operations").EnumerateArray())
        {
            string from = el.GetProperty("from").GetString() ?? "";
            string to = el.GetProperty("to").GetString() ?? "";
            operations.Add(new RenameOperation(from, to));
        }

        return (directory, ts, operations);
    }
}

