private void DoRefreshPreview()
{
    string folder = txtFolder.Text.Trim();
    lblFolderPath.Text = folder;

    lvPreview.BeginUpdate();
    try
    {
        lvPreview.Items.Clear();

        if (folder.Length == 0 || !Directory.Exists(folder))
        {
            currentPlan = null;
            UpdateCounts(0, 0, 0, 0, 0);
            btnApply.Enabled = false;
            SetMessage(folder.Length == 0 ? "No folder selected." : "Folder not found.");
            return;
        }

        RuleSet rules = BuildRuleSet();
        RenamePlan plan;
        try
        {
            plan = RenamePlanner.Create(folder, rules);
        }
        catch (Exception ex)
        {
            currentPlan = null;
            UpdateCounts(0, 0, 0, 0, 0);
            btnApply.Enabled = false;
            SetMessage($"Preview failed: {ex.Message}");
            return;
        }

        currentPlan = plan;
        int index = 1;
        foreach (PlanItem item in plan.Items)
        {
            var lvi = new ListViewItem(new[]
            {
                index.ToString(CultureInfo.InvariantCulture),
                item.Original,
                item.Proposed,
                StatusText(item.Status),
                item.Reason,
            });
            ColorItem(lvi, item.Status);
            lvPreview.Items.Add(lvi);
            index++;
        }

        PlanSummary summary = plan.Summary;
        UpdateCounts(summary.Total, summary.Ok, summary.Collision, summary.Unchanged, summary.Invalid);
        btnApply.Enabled = summary.Ok > 0;
        SetMessage("Plan refreshed.");
    }
    finally
    {
        lvPreview.EndUpdate();
    }
}

private static string StatusText(ItemStatus status) => status switch
{
    ItemStatus.Ok => "Ok",
    ItemStatus.Collision => "Collision",
    ItemStatus.Unchanged => "Unchanged",
    ItemStatus.Invalid => "Invalid",
    _ => status.ToString(),
};

private static void ColorItem(ListViewItem item, ItemStatus status)
{
    switch (status)
    {
        case ItemStatus.Ok:
            item.ForeColor = Color.FromArgb(0, 102, 0);
            break;
        case ItemStatus.Unchanged:
            item.ForeColor = SystemColors.GrayText;
            break;
        case ItemStatus.Collision:
            item.BackColor = Color.FromArgb(255, 224, 224);
            break;
        case ItemStatus.Invalid:
            item.BackColor = Color.FromArgb(255, 236, 200);
            break;
    }
}

private void UpdateCounts(int total, int ok, int collision, int unchanged, int invalid)
{
    lblCounts.Text = string.Create(
        CultureInfo.InvariantCulture,
        $"Total {total} · OK {ok} · Collision {collision} · Unchanged {unchanged} · Invalid {invalid}");
}

private void SetMessage(string text)
{
    lblMessage.Text = text;
}

