private void OnApply(object? sender, EventArgs e)
{
    try
    {
        if (currentPlan is null || currentPlan.Summary.Ok == 0)
        {
            return;
        }

        string folder = txtFolder.Text.Trim();
        int okCount = currentPlan.Summary.Ok;
        DialogResult confirm = MessageBox.Show(
            this,
            $"Rename {okCount} files in {folder}? Files marked collision, invalid or unchanged are skipped.",
            "Confirm rename",
            MessageBoxButtons.YesNo,
            MessageBoxIcon.Question);
        if (confirm != DialogResult.Yes)
        {
            return;
        }

        RenameOutcome outcome = RenameExecutor.Apply(folder, currentPlan, RenameExecutor.DefaultHistoryDirectory);
        RefreshPreview();
        SetMessage($"Renamed {outcome.Renamed}, failed {outcome.Failed}");
        if (outcome.Errors.Count > 0)
        {
            ShowErrors(outcome.Errors);
        }
    }
    catch (Exception ex)
    {
        SetMessage($"Apply failed: {ex.Message}");
    }
}

